const std = @import("std");

const SCCContext = struct {
    graph: [4][4]u8,
    visited: [4]bool,
    stack: [4]u8,
    sp: usize,
    on_stack: [4]bool,
    index_counter: u8,
    indices: [4]u8,
    lowlink: [4]u8,
};

fn strongconnect(ctx: *SCCContext, v: u8) void {
    ctx.visited[v] = true;
    ctx.indices[v] = ctx.index_counter;
    ctx.lowlink[v] = ctx.index_counter;
    ctx.index_counter += 1;
    ctx.stack[ctx.sp] = v;
    ctx.sp += 1;
    ctx.on_stack[v] = true;
    for (0..4) |w| {
        if (ctx.graph[v][w] == 1) {
            if (!ctx.visited[w]) {
                strongconnect(ctx, @intCast(w));
                ctx.lowlink[v] = @min(ctx.lowlink[v], ctx.lowlink[w]);
            } else if (ctx.on_stack[w]) {
                ctx.lowlink[v] = @min(ctx.lowlink[v], ctx.indices[w]);
            }
        }
    }
    if (ctx.lowlink[v] == ctx.indices[v]) {
        while (ctx.sp > 0) {
            ctx.sp -= 1;
            const w = ctx.stack[ctx.sp];
            ctx.on_stack[w] = false;
            std.debug.print("{} ", .{w});
            if (w == v) break;
        }
        std.debug.print("\n", .{});
    }
}

pub fn main() !void {
    var ctx = SCCContext{
        .graph = [_][4]u8{
            [_]u8{ 0, 1, 0, 0 },
            [_]u8{ 0, 0, 1, 0 },
            [_]u8{ 1, 0, 0, 0 },
            [_]u8{ 0, 0, 0, 0 },
        },
        .visited = [_]bool{false} ** 4,
        .stack = undefined,
        .sp = 0,
        .on_stack = [_]bool{false} ** 4,
        .index_counter = 0,
        .indices = [_]u8{ 255, 255, 255, 255 },
        .lowlink = [_]u8{ 255, 255, 255, 255 },
    };
    for (0..4) |v| {
        if (!ctx.visited[v]) strongconnect(&ctx, @intCast(v));
    }
}
